import firebase_admin
from firebase_admin import credentials, auth
from typing import Dict, Any


def get_firebase_app(config: Dict[str, Any]):
    try:
        return firebase_admin.get_app()
    except ValueError:
        cred = credentials.Certificate(config["firebase_service_account_key_path"])
        return firebase_admin.initialize_app(cred, options={"projectId": config["project_id"]})


def get_firebase_auth_client(config: Dict[str, Any]):
    app = get_firebase_app(config)
    return auth, app

import requests
from identity_models import LoginUserPayload, AuthTokens
from typing import Dict, Any


def email_password_login(payload: LoginUserPayload, config: Dict[str, Any]) -> AuthTokens:
    api_key = config["firebase_web_api_key"]
    url = f"https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key={api_key}"
    headers = {"Content-Type": "application/json"}
    data = {"email": payload.email, "password": payload.password, "returnSecureToken": True}

    response = requests.post(url, headers=headers, json=data)
    response.raise_for_status()

    response_data = response.json()
    return AuthTokens(
        id_token=response_data["idToken"],
        refresh_token=response_data["refreshToken"],
        expires_in=int(response_data["expiresIn"])
    )

import requests
from identity_models import RefreshSessionPayload, AuthTokens
from typing import Dict, Any


def refresh_session(payload: RefreshSessionPayload, config: Dict[str, Any]) -> AuthTokens:
    api_key = config["firebase_web_api_key"]
    url = f"https://securetoken.googleapis.com/v1/token?key={api_key}"
    headers = {"Content-Type": "application/json"}
    data = {"grant_type": "refresh_token", "refresh_token": payload.refresh_token}

    response = requests.post(url, headers=headers, json=data)
    response.raise_for_status()

    response_data = response.json()
    return AuthTokens(
        id_token=response_data["id_token"],
        refresh_token=response_data["refresh_token"],
        expires_in=int(response_data["expires_in"])
    )

import requests
from identity_models import PasswordResetPayload
from typing import Dict, Any


def password_reset(payload: PasswordResetPayload, config: Dict[str, Any]):
    api_key = config["firebase_web_api_key"]
    url = f"https://identitytoolkit.googleapis.com/v1/accounts:sendOobCode?key={api_key}"
    headers = {"Content-Type": "application/json"}
    data = {"requestType": "PASSWORD_RESET", "email": payload.email}

    response = requests.post(url, headers=headers, json=data)
    response.raise_for_status()

    return {"message": "Password reset email sent"}

from google.cloud import firestore
from identity_models import ProfileNoteStorePayload
from typing import Dict, Any


def profile_note_store(payload: ProfileNoteStorePayload, config: Dict[str, Any]):
    db = firestore.Client(project=config["google_cloud_project_id"])
    doc_ref = db.collection("profile_notes").document(payload.user_id)
    doc_ref.set({
        "note_content": payload.note_content,
        "metadata": payload.metadata,
        "timestamp": firestore.SERVER_TIMESTAMP,
    })
    return {"status": "success", "user_id": payload.user_id}
